// Embeds src/hook.py into the plugin as bin/hook-src.js.
// With Marketplace DRM the plugin's shipped files are encrypted, so the hook cannot be copied out as a raw .py file;
// the plugin writes it from this string instead.  Run after editing src/hook.py:  node tools/embed-hook.js
"use strict";
const fs = require("fs"), path = require("path");
const ROOT = path.resolve(__dirname, "..");
const py = fs.readFileSync(path.join(ROOT, "src/hook.py"), "utf8");
fs.writeFileSync(path.join(ROOT, "io.github.jacopopiogargano.ccstatus.sdPlugin/bin/hook-src.js"),
  "// Generated by tools/embed-hook.js from src/hook.py. Do not edit.\nmodule.exports = " + JSON.stringify(py) + ";\n");
console.log("wrote bin/hook-src.js");
